def strings(lang):
    """UI strings for `lang` (e.g. "fr", "pt-BR"), falling back to English key by key."""
    code = (lang or "en").lower().split("-")[0].split("_")[0]
    return {**STRINGS["en"], **STRINGS.get(code, {})}, code
